const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * True once the plan's retention window has elapsed since `archivedAt`. An
 * expired row can no longer be restored, and the retention sweep purges it.
 */
export function isExpiredArchive(
  archivedAt: IsoTimestamp,
  retentionDays: number,
  now: Date = new Date(),
): boolean {
  return now.getTime() - Date.parse(archivedAt) >= retentionDays * MS_PER_DAY;
}

/** The instant before which archived rows have expired. */
export function retentionCutoff(retentionDays: number, now: Date): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - retentionDays * MS_PER_DAY));
}

