cat > tests/server/zz-scratch-restore.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { getDb, searchIndex, usageRepoProbe } from "@/server/db";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import { RestoreRefusedError } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
const DAY = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  tenant = await createTenant("scratch");
});
afterAll(() => {
  vi.useRealTimers();
  unregisterEventHandlers();
  cleanup();
});

describe("restore + purge", () => {
  it("restores within window, refuses when not archived, purges after window", async () => {
    const a = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "A" }));
    const b = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "B" }));
    expect(b.number).toBe(2);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, a.id);
    expect((await usageRepo.getUsage(tenant.org.id)).issuesUsed).toBe(1);
    const restored = await issueService.restoreIssue(tenant.actors.member, tenant.org.id, a.id);
    expect(restored.archivedAt).toBeNull();
    expect(restored.number).toBe(1);
    expect((await usageRepo.getUsage(tenant.org.id)).issuesUsed).toBe(2);
    await expect(issueService.restoreIssue(tenant.actors.member, tenant.org.id, a.id)).rejects.toMatchObject({ reason: "not_archived" });
    await expect(issueService.restoreIssue(tenant.actors.member, tenant.org.id, a.id)).rejects.toBeInstanceOf(RestoreRefusedError);

    // B: archive, add comment + attachment, then purge after window
    await commentService.createComment?.call(null as never, tenant.actors.member, {} as never).catch(() => undefined);
    const att = await attachmentRepo.insertAttachment({ orgId: tenant.org.id, issueId: b.id, filename: "x.bin", contentType: "application/octet-stream", sizeBytes: 2.5 * 1024 * 1024 } as never, tenant.userIds.member);
    expect(att).toBeTruthy();
    await usageRepo.incrementUsage(tenant.org.id, { storageMbUsed: 3 });
    const before = await usageRepo.getUsage(tenant.org.id);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, b.id);

    const future = new Date(Date.now() + 40 * DAY);
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(future);
    await expect(issueService.restoreIssue(tenant.actors.member, tenant.org.id, b.id)).rejects.toMatchObject({ reason: "expired" });
    vi.useRealTimers();

    // Sweep at a time past retention (free=30d, growth=365d). Growth => use +400d.
    const later = new Date(Date.now() + 400 * DAY);
    await runCleanupArchivedJob(later);

    expect(await issueRepo.findIssueById(tenant.org.id, b.id)).toBeNull();
    expect(await attachmentRepo.listAttachments(tenant.org.id, b.id)).toHaveLength(0);
    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.storageMbUsed).toBe(before.storageMbUsed - 3);
    expect(after.issuesUsed).toBe(2);
    await expect(issueService.restoreIssue(tenant.actors.member, tenant.org.id, b.id)).rejects.toMatchObject({ name: "NotFoundError" });
    await expect(issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id)).resolves.toBe(3);
    const docs = getDb().select().from(searchIndex).all().filter((d) => d.subjectId === b.id);
    expect(docs).toHaveLength(0);
  });
});
EOF
